  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&display=swap" rel="stylesheet">
  <style>
    :root{--pine-950:#061a15;--pine-900:#09251d;--pine-850:#0d3027;--pine-800:#123b30;--pine-700:#1b5242;--acid:#dffc62;--ember:#f27b4a;--cream:#fffdf6;--oat:#f0ecdf;--moss:#b7c9a3;--ink:#16231e;--muted:rgba(22,35,30,.58);--line:rgba(9,37,29,.12);--shadow:0 28px 80px -48px rgba(6,26,21,.62);--card-shadow:0 20px 54px -38px rgba(6,26,21,.48)}
    *{box-sizing:border-box}html{background:var(--oat);scroll-behavior:smooth}body{margin:0;overflow-x:hidden;background:var(--oat);color:var(--ink);font-family:"DM Sans",sans-serif;text-rendering:optimizeLegibility}button,input,select,textarea{font:inherit}button,a{touch-action:manipulation}a{color:inherit;text-decoration:none}img{display:block;max-width:100%}[hidden]{display:none!important}::selection{background:var(--acid);color:var(--pine-950)}
    .shell{width:min(1460px,calc(100% - 32px));margin-inline:auto}.topo{background-image:radial-gradient(circle at 14% 16%,rgba(223,252,98,.14),transparent 20%),radial-gradient(circle at 88% 20%,rgba(242,123,74,.13),transparent 16%),url("data:image/svg+xml,%3Csvg width='760' height='760' viewBox='0 0 760 760' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' stroke='%23fff' stroke-opacity='.06' stroke-width='1.05'%3E%3Cpath d='M74 206c43-106 166-167 278-119 89 39 107 147 52 218-51 66-143 59-194 124-58 73-49 188-142 228-91 38-186-37-164-132 20-89 111-106 122-190 8-57-5-88 48-129Z'/%3E%3Cpath d='M112 231c34-81 128-126 214-90 69 29 82 113 41 167-39 50-110 45-150 95-44 55-38 144-109 174-70 29-143-29-126-102 15-68 85-81 94-146 6-43-4-67 36-98Z'/%3E%3Cpath d='M493 410c57-79 161-89 227-18 60 64 24 169-55 198-71 26-142-17-201 28-52 40-62 123-129 129-74 6-126-73-84-135 38-56 112-39 155-92 35-43 39-79 87-110Z'/%3E%3C/g%3E%3C/svg%3E");background-size:auto,auto,760px 760px}
    .site-header{position:sticky;top:0;z-index:50;padding:12px 0;background:linear-gradient(180deg,rgba(240,236,223,.96),rgba(240,236,223,.78),transparent)}.nav{display:flex;align-items:center;gap:16px;padding:10px 12px 10px 16px;border:1px solid rgba(255,255,255,.12);border-radius:22px;background:rgba(6,26,21,.89);box-shadow:0 24px 70px -46px rgba(0,0,0,.9);backdrop-filter:blur(22px) saturate(130%);color:#fff}.brand{display:flex;align-items:center;gap:11px;min-width:0}.brand-mark{display:grid;place-items:center;width:42px;height:42px;flex:0 0 auto;border:1px solid rgba(223,252,98,.42);border-radius:15px;background:rgba(223,252,98,.08);color:var(--acid)}.brand-copy{min-width:0;line-height:1}.brand-copy strong{display:block;font-family:"Fraunces",serif;font-size:18px;font-weight:600;letter-spacing:-.02em}.brand-copy span{display:block;margin-top:5px;color:rgba(255,255,255,.5);font-size:10px;font-weight:700;letter-spacing:.18em;text-transform:uppercase;white-space:nowrap}.main-nav{display:flex;align-items:center;gap:6px;margin-left:auto}.main-nav a{padding:10px 12px;border-radius:12px;color:rgba(255,255,255,.68);font-size:13px;font-weight:600}.main-nav a:hover{background:rgba(255,255,255,.07);color:#fff}.nav-actions{display:flex;align-items:center;gap:8px}.ticket-cta{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 16px;border-radius:13px;background:var(--acid);color:var(--pine-950);font-size:13px;font-weight:800;white-space:nowrap}.menu-btn{display:none;place-items:center;width:40px;height:40px;border:0;border-radius:13px;background:rgba(255,255,255,.07);color:#fff;cursor:pointer}
    .layout{display:grid;grid-template-columns:250px minmax(0,1fr);gap:24px;padding:18px 0 96px}.sidebar{position:sticky;top:92px;align-self:start;padding:18px;border:1px solid var(--line);border-radius:26px;background:rgba(255,253,246,.8);box-shadow:var(--card-shadow);backdrop-filter:blur(18px)}.profile-mini{display:flex;align-items:center;gap:12px;padding:8px 8px 20px;border-bottom:1px solid var(--line)}.avatar{position:relative;display:grid;place-items:center;width:50px;height:50px;flex:0 0 auto;border-radius:18px;background:var(--pine-900);color:var(--acid);font-family:"Fraunces",serif;font-size:18px;font-weight:700}.avatar:after{content:"";position:absolute;right:-2px;bottom:-2px;width:13px;height:13px;border:3px solid var(--cream);border-radius:50%;background:#54c97a}.profile-mini strong{display:block;font-size:14px}.profile-mini span span{display:block;margin-top:4px;color:rgba(22,35,30,.54);font-size:11px}.side-nav{display:grid;gap:6px;padding:16px 0}.side-nav a{display:flex;align-items:center;gap:11px;padding:11px 12px;border-radius:14px;color:rgba(22,35,30,.64);font-size:13px;font-weight:650;transition:.2s ease}.side-nav a:hover{background:rgba(9,37,29,.06);color:var(--pine-900)}.side-nav a.active{background:var(--pine-900);color:#fff}.side-nav svg{width:18px;height:18px;flex:0 0 auto}.side-help{padding:15px;border-radius:18px;background:var(--oat)}.side-help strong{display:block;font-family:"Fraunces",serif;font-size:17px}.side-help p{margin:7px 0 12px;color:rgba(22,35,30,.6);font-size:11px;line-height:1.55}.side-help a{color:var(--pine-900);font-size:12px;font-weight:800}
    .content{min-width:0}.hero{position:relative;overflow:hidden;display:grid;grid-template-columns:minmax(0,1fr) 360px;min-height:330px;border-radius:34px;background:var(--pine-900);color:#fff;box-shadow:var(--shadow)}.hero-copy{position:relative;z-index:3;display:flex;flex-direction:column;justify-content:center;padding:40px 44px}.eyebrow{display:inline-flex;align-items:center;gap:8px;width:max-content;padding:7px 10px;border:1px solid rgba(223,252,98,.22);border-radius:999px;background:rgba(223,252,98,.08);color:var(--acid);font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.eyebrow-dot{width:7px;height:7px;border-radius:50%;background:var(--acid);box-shadow:0 0 0 7px rgba(223,252,98,.1)}.hero h1{margin:20px 0 12px;font-family:"Fraunces",serif;font-size:clamp(40px,4.6vw,66px);font-weight:600;letter-spacing:-.055em;line-height:.98}.hero h1 em{color:var(--acid);font-style:italic}.hero-copy>p{max-width:650px;margin:0;color:rgba(255,255,255,.66);font-size:15px;line-height:1.7}.completion{display:flex;align-items:center;gap:16px;margin-top:24px}.completion-ring{--value:82;position:relative;display:grid;place-items:center;width:62px;height:62px;border-radius:50%;background:conic-gradient(var(--acid) calc(var(--value)*1%),rgba(255,255,255,.12) 0)}.completion-ring:before{content:"";position:absolute;inset:6px;border-radius:50%;background:var(--pine-900)}.completion-ring strong{position:relative;z-index:2;font-size:14px}.completion span strong{display:block;font-size:13px}.completion span small{display:block;margin-top:4px;color:rgba(255,255,255,.52);font-size:11px}.hero-visual{position:relative;display:grid;place-items:center;min-height:330px;padding:28px}.hero-visual:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,var(--pine-900),rgba(9,37,29,.18) 38%,rgba(9,37,29,.08)),url("https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1100&q=86") center/cover;opacity:.76}.profile-card{position:relative;z-index:3;width:min(280px,100%);padding:24px;border:1px solid rgba(255,255,255,.17);border-radius:27px;background:linear-gradient(145deg,rgba(255,255,255,.15),rgba(255,255,255,.045));box-shadow:0 30px 70px -34px rgba(0,0,0,.75);backdrop-filter:blur(20px);transform:rotate(2.5deg)}.profile-photo{position:relative;display:grid;place-items:center;width:92px;height:92px;margin:0 auto 18px;border:1px solid rgba(223,252,98,.4);border-radius:30px;background:rgba(223,252,98,.08);color:var(--acid);font-family:"Fraunces",serif;font-size:34px;font-weight:700}.profile-photo button{position:absolute;right:-7px;bottom:-7px;display:grid;place-items:center;width:34px;height:34px;border:4px solid var(--pine-900);border-radius:12px;background:var(--acid);color:var(--pine-950);cursor:pointer}.profile-card h2{margin:0;text-align:center;font-family:"Fraunces",serif;font-size:25px}.profile-card p{margin:7px 0 18px;text-align:center;color:rgba(255,255,255,.58);font-size:11px}.profile-code{padding:11px;border-radius:15px;background:rgba(6,26,21,.55);text-align:center;color:var(--acid);font-size:10px;font-weight:900;letter-spacing:.16em}
    .tabs{position:sticky;top:87px;z-index:18;display:flex;gap:6px;margin:16px 0;padding:7px;border:1px solid var(--line);border-radius:18px;background:rgba(240,236,223,.88);backdrop-filter:blur(18px);overflow-x:auto;scrollbar-width:none}.tabs::-webkit-scrollbar{display:none}.tabs button{flex:0 0 auto;min-height:40px;padding:0 14px;border:0;border-radius:12px;background:transparent;color:var(--muted);cursor:pointer;font-size:12px;font-weight:800;white-space:nowrap}.tabs button.active{background:var(--pine-900);color:#fff}.section-grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(300px,.75fr);gap:16px}.stack{display:grid;gap:16px}.card{padding:24px;border:1px solid var(--line);border-radius:27px;background:var(--cream);box-shadow:var(--card-shadow)}.card-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:22px}.card-kicker{margin:0 0 7px;color:var(--pine-700);font-size:9px;font-weight:900;letter-spacing:.16em;text-transform:uppercase}.card h2,.card h3{margin:0;font-family:"Fraunces",serif;font-weight:600;letter-spacing:-.025em}.card h2{font-size:26px}.card h3{font-size:21px}.card-head p:not(.card-kicker){max-width:520px;margin:7px 0 0;color:var(--muted);font-size:12px;line-height:1.55}.status-pill{display:inline-flex;align-items:center;gap:7px;flex:0 0 auto;padding:8px 10px;border-radius:999px;background:rgba(84,201,122,.11);color:#257344;font-size:10px;font-weight:900}.status-pill:before{content:"";width:7px;height:7px;border-radius:50%;background:#54c97a}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.field{display:grid;gap:7px}.field.full{grid-column:1/-1}.field label{font-size:11px;font-weight:800}.field small{color:var(--muted);font-size:10px}.control{width:100%;min-height:48px;padding:0 14px;border:1px solid var(--line);border-radius:14px;background:#fff;color:var(--ink);outline:none;transition:.2s ease}.control:focus{border-color:rgba(9,37,29,.42);box-shadow:0 0 0 4px rgba(9,37,29,.06)}textarea.control{min-height:110px;padding:13px 14px;resize:vertical}.phone-row{display:grid;grid-template-columns:92px minmax(0,1fr);gap:9px}.field-error{display:none;color:#a94228;font-size:10px;font-weight:700}.field.invalid .control{border-color:#d56b4e}.field.invalid .field-error{display:block}.actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:9px;margin-top:20px;padding-top:20px;border-top:1px solid var(--line)}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:0 17px;border:0;border-radius:14px;cursor:pointer;font-size:12px;font-weight:850;transition:.22s ease}.btn-primary{background:var(--pine-900);color:#fff}.btn-primary:hover{transform:translateY(-2px)}.btn-acid{background:var(--acid);color:var(--pine-950)}.btn-ghost{border:1px solid var(--line);background:#fff;color:var(--pine-900)}.btn-danger{background:rgba(242,123,74,.12);color:#a64322}.preference-list{display:grid;gap:10px}.choice{display:flex;align-items:flex-start;gap:11px;padding:13px;border:1px solid var(--line);border-radius:16px;background:#fff;cursor:pointer;transition:.2s ease}.choice:hover{border-color:rgba(9,37,29,.28)}.choice input{width:17px;height:17px;margin:1px 0 0;accent-color:var(--pine-900)}.choice strong{display:block;font-size:12px}.choice span span{display:block;margin-top:4px;color:var(--muted);font-size:10px;line-height:1.45}.tag-grid{display:flex;flex-wrap:wrap;gap:8px}.tag{position:relative}.tag input{position:absolute;opacity:0;pointer-events:none}.tag label{display:inline-flex;align-items:center;min-height:38px;padding:0 12px;border:1px solid var(--line);border-radius:999px;background:#fff;color:var(--muted);cursor:pointer;font-size:11px;font-weight:800}.tag input:checked+label{border-color:var(--pine-900);background:var(--pine-900);color:#fff}.security-list,.data-list{display:grid;gap:10px}.security-item,.data-item{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px;border:1px solid var(--line);border-radius:17px;background:#fff}.item-icon{display:grid;place-items:center;width:40px;height:40px;flex:0 0 auto;border-radius:13px;background:var(--oat);color:var(--pine-800)}.item-copy{min-width:0;margin-right:auto}.item-copy strong{display:block;font-size:12px}.item-copy span{display:block;margin-top:4px;color:var(--muted);font-size:10px;line-height:1.4}.text-btn{padding:7px 0;border:0;background:transparent;color:var(--pine-700);cursor:pointer;font-size:10px;font-weight:900;white-space:nowrap}.progress-card{background:var(--pine-900);color:#fff}.progress-card p{color:rgba(255,255,255,.58)}.progress-track{height:8px;margin:18px 0 10px;border-radius:999px;background:rgba(255,255,255,.1);overflow:hidden}.progress-track span{display:block;width:82%;height:100%;border-radius:inherit;background:var(--acid)}.checklist{display:grid;gap:10px;margin-top:18px}.check-item{display:flex;align-items:center;gap:9px;font-size:11px}.check-dot{display:grid;place-items:center;width:22px;height:22px;border-radius:8px;background:rgba(223,252,98,.12);color:var(--acid)}.check-item.missing .check-dot{background:rgba(242,123,74,.13);color:var(--ember)}.session{display:flex;align-items:center;gap:12px;padding:13px 0;border-bottom:1px solid var(--line)}.session:last-child{border-bottom:0}.session-device{display:grid;place-items:center;width:38px;height:38px;border-radius:13px;background:var(--oat)}.session strong{display:block;font-size:11px}.session span{display:block;margin-top:3px;color:var(--muted);font-size:9px}.session-current{margin-left:auto;color:#257344;font-size:9px;font-weight:900}
    .mobile-nav{display:none;position:fixed;z-index:45;left:10px;right:10px;bottom:max(10px,env(safe-area-inset-bottom));grid-template-columns:repeat(5,1fr);padding:7px;border:1px solid rgba(255,255,255,.12);border-radius:20px;background:rgba(6,26,21,.94);box-shadow:0 24px 70px -30px rgba(0,0,0,.76);backdrop-filter:blur(20px);color:#fff}.mobile-nav a{display:grid;place-items:center;gap:4px;padding:7px 2px;border-radius:13px;color:rgba(255,255,255,.52);font-size:8px;font-weight:800}.mobile-nav a.active{background:rgba(223,252,98,.12);color:var(--acid)}.mobile-nav svg{width:17px;height:17px}.mobile-menu{position:fixed;z-index:70;inset:0;display:grid;align-content:start;padding:18px;background:var(--pine-950);color:#fff;transform:translateY(-105%);transition:.34s cubic-bezier(.22,.8,.2,1)}.mobile-menu.open{transform:translateY(0)}.mobile-menu-head{display:flex;align-items:center;justify-content:space-between}.mobile-menu-links{display:grid;gap:8px;margin-top:45px}.mobile-menu-links a{padding:16px 4px;border-bottom:1px solid rgba(255,255,255,.1);font-family:"Fraunces",serif;font-size:26px}.modal{position:fixed;z-index:80;inset:0;display:grid;place-items:center;padding:18px;background:rgba(6,26,21,.72);backdrop-filter:blur(13px);opacity:0;pointer-events:none;transition:.22s ease}.modal.open{opacity:1;pointer-events:auto}.modal-card{position:relative;width:min(540px,100%);max-height:min(760px,calc(100vh - 36px));overflow:auto;padding:27px;border-radius:28px;background:var(--cream);box-shadow:0 40px 100px -45px #000}.modal-close{display:grid;place-items:center;width:38px;height:38px;border:0;border-radius:13px;background:var(--oat);color:var(--pine-900);cursor:pointer}.modal-card>.modal-close{position:absolute;right:18px;top:18px}.modal-card h3{margin:10px 0 8px;font-family:"Fraunces",serif;font-size:28px}.modal-card>p{margin:0 38px 20px 0;color:var(--muted);font-size:12px;line-height:1.55}.modal-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}.danger-box{padding:16px;border:1px solid rgba(242,123,74,.24);border-radius:18px;background:rgba(242,123,74,.07);color:#7f351f;font-size:11px;line-height:1.55}.toast{position:fixed;z-index:100;right:18px;bottom:18px;max-width:360px;padding:13px 15px;border-radius:15px;background:var(--pine-950);color:#fff;box-shadow:0 20px 50px -28px #000;font-size:11px;font-weight:750;opacity:0;transform:translateY(14px);pointer-events:none;transition:.24s ease}.toast.show{opacity:1;transform:translateY(0)}
    @media(max-width:1120px){.main-nav{display:none}.menu-btn{display:grid}.layout{grid-template-columns:220px minmax(0,1fr)}.hero{grid-template-columns:minmax(0,1fr) 300px}.section-grid{grid-template-columns:1fr}.aside-stack{grid-template-columns:repeat(2,minmax(0,1fr));display:grid;gap:16px}}
    @media(max-width:820px){.shell{width:min(100% - 22px,760px)}.site-header{padding:8px 0}.nav{border-radius:18px;padding:8px 9px 8px 12px}.brand-copy span{display:none}.ticket-cta{min-height:38px;padding:0 12px}.layout{display:block;padding-top:10px}.sidebar{display:none}.hero{display:block;min-height:0;border-radius:27px}.hero-copy{padding:34px 24px 26px}.hero-visual{min-height:285px;padding:24px}.profile-card{width:min(290px,86%)}.tabs{top:71px;margin:12px 0}.mobile-nav{display:grid}.content{padding-bottom:64px}.aside-stack{grid-template-columns:1fr}}
    @media(max-width:560px){.shell{width:calc(100% - 16px)}.nav{gap:8px}.brand-mark{width:38px;height:38px;border-radius:13px}.brand-copy strong{font-size:16px}.ticket-cta{font-size:11px;padding:0 10px}.hero-copy{padding:29px 19px 23px}.hero h1{font-size:39px}.hero-copy>p{font-size:13px}.completion{gap:12px}.hero-visual{min-height:255px}.profile-card{width:100%;padding:20px}.profile-photo{width:78px;height:78px;border-radius:25px}.tabs{margin-inline:-1px}.tabs button{padding:0 12px}.card{padding:19px;border-radius:23px}.card-head{display:block}.status-pill{margin-top:12px}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}.phone-row{grid-template-columns:80px minmax(0,1fr)}.actions{justify-content:stretch}.actions .btn{flex:1}.security-item,.data-item{align-items:flex-start}.text-btn{padding-top:2px}.modal{align-items:end;padding:0}.modal-card{width:100%;max-height:88vh;border-radius:26px 26px 0 0;padding:24px 18px calc(24px + env(safe-area-inset-bottom))}.modal-actions{display:grid}.toast{left:12px;right:12px;bottom:88px}.nav-actions{gap:6px}}
  </style>
