  <script>
    (()=>{'use strict';const $=(s,c=document)=>c.querySelector(s),$$=(s,c=document)=>[...c.querySelectorAll(s)];const body=document.body,menu=$('#mobileMenu'),toast=$('#toast');let activeModal=null;const lock=()=>body.style.overflow='hidden',unlock=()=>body.style.overflow='';const showToast=message=>{if(!toast)return;toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2600)};const openMenu=()=>{menu?.classList.add('open');menu?.setAttribute('aria-hidden','false');lock()},closeMenu=()=>{menu?.classList.remove('open');menu?.setAttribute('aria-hidden','true');unlock()};const openModal=id=>{activeModal=$(id);activeModal?.classList.add('open');activeModal?.setAttribute('aria-hidden','false');lock()},closeModal=()=>{activeModal?.classList.remove('open');activeModal?.setAttribute('aria-hidden','true');activeModal=null;unlock()};
      $('#menuOpen')?.addEventListener('click',openMenu);$('#menuClose')?.addEventListener('click',closeMenu);document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();closeModal()}});$$('[data-close-modal]').forEach(b=>b.addEventListener('click',closeModal));$$('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModal()}));
      $$('.tabs button').forEach(button=>button.addEventListener('click',()=>{$$('.tabs button').forEach(x=>x.classList.remove('active'));button.classList.add('active');$$('.tab-panel').forEach(panel=>panel.hidden=panel.id!==button.dataset.tab);window.scrollTo({top:Math.max(0,$('.tabs').offsetTop-82),behavior:'smooth'})}));
      const validateField=(field,test)=>{field.closest('.field')?.classList.toggle('invalid',!test);return test};$('#personalForm')?.addEventListener('submit',e=>{e.preventDefault();const first=$('#firstName'),last=$('#lastName'),email=$('#email');const ok=[validateField(first,first.value.trim().length>1),validateField(last,last.value.trim().length>1),validateField(email,/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value))].every(Boolean);if(ok)showToast('Datele personale au fost actualizate.')});$('#resetPersonal')?.addEventListener('click',()=>{$('#personalForm')?.reset();showToast('Modificările nesalvate au fost anulate.')});$('#addressForm')?.addEventListener('submit',e=>{e.preventDefault();showToast('Adresa implicită a fost salvată.')});$('#avatarButton')?.addEventListener('click',()=>showToast('Încărcarea fotografiei este demonstrativă.'));$('#savePreferences')?.addEventListener('click',()=>showToast('Preferințele au fost salvate.'));$('#saveSafety')?.addEventListener('click',()=>showToast('Informațiile de siguranță au fost salvate.'));
      $('#passwordOpen')?.addEventListener('click',()=>openModal('#passwordModal'));$('#passwordForm')?.addEventListener('submit',e=>{e.preventDefault();const a=$('#newPassword').value,b=$('#confirmPassword').value;if(a.length<10)return showToast('Parola trebuie să aibă minimum 10 caractere.');if(a!==b)return showToast('Parolele nu coincid.');closeModal();e.target.reset();showToast('Parola a fost actualizată.')});$('#twoFactorButton')?.addEventListener('click',e=>{e.currentTarget.textContent='Activ';showToast('Autentificarea în doi pași a fost activată demonstrativ.')});$('#magicButton')?.addEventListener('click',e=>{e.currentTarget.textContent=e.currentTarget.textContent==='Dezactivează'?'Activează':'Dezactivează';showToast('Setarea pentru link magic a fost actualizată.')});$$('[data-revoke]').forEach(b=>b.addEventListener('click',()=>{b.closest('.session')?.remove();showToast('Sesiunea a fost închisă.')}));$('#logoutAll')?.addEventListener('click',()=>showToast('Toate celelalte sesiuni au fost închise.'));
      $('#downloadData')?.addEventListener('click',()=>showToast('Exportul datelor va fi trimis prin email.'));$('#marketingToggle')?.addEventListener('click',e=>{e.currentTarget.textContent=e.currentTarget.textContent==='Active'?'Inactive':'Active';showToast('Preferința de marketing a fost actualizată.')});$('#deleteOpen')?.addEventListener('click',()=>openModal('#deleteModal'));$('#deleteAccount')?.addEventListener('click',()=>{if($('#deleteConfirm').value.trim().toUpperCase()!=='ȘTERGE')return showToast('Scrie ȘTERGE pentru confirmare.');closeModal();showToast('Solicitarea de ștergere a fost înregistrată.')});
      if(!matchMedia('(prefers-reduced-motion: reduce)').matches){$$('.hero-copy > *').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(20px)'},{opacity:1,transform:'translateY(0)'}],{duration:600,delay:60+i*70,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'}));$('.profile-card')?.animate([{opacity:0,transform:'translateY(22px) rotate(7deg) scale(.96)'},{opacity:1,transform:'translateY(0) rotate(2.5deg) scale(1)'}],{duration:850,delay:160,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'});const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.animate([{opacity:0,transform:'translateY(14px)'},{opacity:1,transform:'translateY(0)'}],{duration:450,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'});observer.unobserve(entry.target)}}),{threshold:.08});$$('.card').forEach(el=>observer.observe(el))}
    })();
