    function nvAuth(){ try { return JSON.parse(localStorage.getItem('nordvale_auth')||'null'); } catch(e){ return null; } }
    var a = nvAuth();
    if(!a || !a.token){ location.href='/autentificare?next='+encodeURIComponent(location.pathname+location.search); return; }
    var AH = { 'Authorization':'Bearer '+a.token };
    function api(ac,opt){ opt=opt||{}; opt.headers=Object.assign({},AH,opt.headers||{}); return fetch('/api/proxy.php?action='+ac,opt).then(function(r){return r.json().catch(function(){return{};});}).catch(function(){return{};}); }
    function post(ac,b){ return api(ac,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b||{})}); }
    function initials(n){ n=(n||'').trim(); if(!n)return 'N'; var p=n.split(/\s+/); return (((p[0]||'')[0]||'')+((p[1]||'')[0]||'')).toUpperCase()||'N'; }
    function toast(msg){ var t=document.querySelector('#toast'); if(!t){ alert(msg); return; } t.textContent=msg; t.classList.add('show'); clearTimeout(window.__nvtt); window.__nvtt=setTimeout(function(){ t.classList.remove('show'); },2600); }
    function hydrateUser(u){ if(!u)return; var name=u.name||(((u.first_name||'')+' '+(u.last_name||'')).trim())||'Cont Nordvale'; window.__nvName=name; var box=document.querySelector('.profile-mini'); if(box){ var av=box.querySelector('.avatar'); if(av)av.textContent=initials(name); var st=box.querySelector('strong'); if(st)st.textContent=name; var em=box.querySelector('strong + span'); if(em&&u.email)em.textContent=u.email; } var pc=document.querySelector('.profile-card h2'); if(pc&&name)pc.textContent=name; }
    document.querySelectorAll('a,button').forEach(function(el){ if((el.textContent||'').trim()==='Deconectare'){ el.addEventListener('click',function(ev){ ev.preventDefault(); post('logout').finally(function(){ localStorage.removeItem('nordvale_auth'); location.href='/'; }); }); } });

    function fillProfile(u){ if(!u)return; var name=u.name||''; var parts=name.split(/\s+/); var fn=document.querySelector('#firstName'); var ln=document.querySelector('#lastName'); if(fn&&parts[0])fn.value=parts[0]; if(ln&&parts.length>1)ln.value=parts.slice(1).join(' '); var em=document.querySelector('#email'); if(em&&u.email)em.value=u.email; var ph=document.querySelector('#phone'); if(ph&&u.phone)ph.value=u.phone; }
    hydrateUser(a.user); fillProfile(a.user);
    api('me').then(function(d){ if(d&&d.success&&d.data){ a.user=Object.assign({},a.user,d.data); try{localStorage.setItem('nordvale_auth',JSON.stringify(a));}catch(e){} hydrateUser(a.user); fillProfile(a.user); } });

    var pf=document.querySelector('#personalForm');
    if(pf){ var np=pf.cloneNode(true); pf.parentNode.replaceChild(np,pf); pf=np;
      pf.addEventListener('submit',function(e){ e.preventDefault(); var fn=(pf.querySelector('#firstName')||{}).value||''; var ln=(pf.querySelector('#lastName')||{}).value||''; var ph=(pf.querySelector('#phone')||{}).value||''; fn=fn.trim(); ln=ln.trim(); if(fn.length<2||ln.length<2){ toast('Completează prenumele și numele.'); return; } var btn=pf.querySelector('[type="submit"]'); if(btn)btn.disabled=true; post('acc-profile',{first_name:fn,last_name:ln,phone:ph}).then(function(r){ if(r&&r.success){ if(r.data&&r.data.name){ a.user=Object.assign({},a.user,{name:r.data.name,phone:ph}); try{localStorage.setItem('nordvale_auth',JSON.stringify(a));}catch(e2){} hydrateUser(a.user); } toast('Datele personale au fost salvate.'); } else { toast((r&&r.error)||'Eroare la salvarea datelor.'); } }).finally(function(){ if(btn)btn.disabled=false; }); });
      var rp=pf.querySelector('#resetPersonal'); if(rp)rp.addEventListener('click',function(){ fillProfile(a.user); toast('Modificările nesalvate au fost anulate.'); });
    }

    var pw=document.querySelector('#passwordForm');
    if(pw){ var np2=pw.cloneNode(true); pw.parentNode.replaceChild(np2,pw); pw=np2;
      pw.querySelectorAll('[data-close-modal]').forEach(function(b){ b.addEventListener('click',function(){ var m=pw.closest('.modal'); if(m){ m.classList.remove('open'); m.setAttribute('aria-hidden','true'); document.body.style.overflow=''; } }); });
      pw.addEventListener('submit',function(e){ e.preventDefault(); var cur=(pw.querySelector('#currentPassword')||{}).value||''; var a1=(pw.querySelector('#newPassword')||{}).value||''; var a2=(pw.querySelector('#confirmPassword')||{}).value||''; if(a1.length<8){ toast('Parola trebuie să aibă minimum 8 caractere.'); return; } if(a1!==a2){ toast('Parolele nu coincid.'); return; } post('acc-password',{current_password:cur,password:a1,password_confirmation:a2}).then(function(r){ if(r&&r.success){ toast('Parola a fost actualizată.'); pw.reset(); var m=pw.closest('.modal'); if(m){ m.classList.remove('open'); m.setAttribute('aria-hidden','true'); document.body.style.overflow=''; } } else { toast((r&&r.error)||'Parola curentă este incorectă.'); } }); });
    }
  })();
  </script>
</body>
</html>
